1	// group schedule-report 子命令:按本地每周运行时间表把查询范围划分为运行与
2	// 非运行两类时段,分别核查分组能耗的只读报表,用于核查停运消耗。
3	//
4	// - 时间表为零个或多个每周窗口:开始星期 + 起止 HH:mm。开始限 00:00-23:59,
5	//   结束另可 24:00;同值起止拒绝;结束早于开始即跨至下一日(尾段沿用开始
6	//   日规则,周日可跨至周一)。窗口起点含、终点不含,重叠或重复取并集;空表
7	//   (零个窗口)表示全部非运行。
8	// - 分类按实际时刻的当地日期与墙钟:每秒只属一类;夏令时跳过时段不虚构
9	//   覆盖,回拨重复时段各自分类,不套固定偏移或日长。--tz 只解释时间表,
10	//   不重新解释起止时刻或已存读数。
11	// - 能耗口径与 group daily 相同:按当时生效成员与完整读数时序,全部成员
12	//   可信才累加消耗,任一成员下降优先为异常,否则任一成员未知为未知;首个
13	//   版本生效前、读数首末之外与孤立读数未知,不外推。采样限制按原始相邻
14	//   区间判断,裁切不使过长区间可信,等于限制仍可信;有效片段取原区间起点
15	//   累计比例向下取整的两端差,切分不重置起点;BigInt 精确计算,kWh 固定
16	//   三位小数。
17	// - 两类覆盖合计等于查询时长,消耗合计等于同范围、同限制的分组日报,拆开
18	//   查询相加一致;覆盖按时间计,不叠加成员秒数。
19	// - 只读:不改写时间表或业务存储,不自动评估;修正撤销后重查使用当前读数。
20	//   成功(含不可计算结果)返回 0;非法时间表返回 2;时间表文件不可读、未知
21	//   分组、所用存储损坏或全库重复读数身份返回 1,指出原因,不输出部分报表。
22	
23	import { readFileSync } from 'node:fs';
24	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
25	import { formatIsoUtc, parseUtcDate } from './time.ts';
26	import { loadTimezone, wallSegments } from './tz.ts';
27	import { formatKwh } from './value.ts';
28	import { formatGapLine, maxIntervalText, mergeGaps, type GapDetail } from './report.ts';
29	import {
30	  computeGroupSegment,
31	  loadCheckedSeriesByDevice,
32	  loadGroups,
33	  type Group,
34	} from './groups.ts';
35	
36	function err(message: string): void {
37	  console.error(`meterwatch: ${message}`);
38	}
39	
40	export interface ScheduleWindow {
41	  /** 开始星期,0=周日 .. 6=周六。 */
42	  startDow: number;
43	  /** 开始当日的起始分钟,0..1439。 */
44	  startMin: number;
45	  /** 相对开始日的结束分钟(不含),恒大于 startMin;结束早于开始时 +1440 跨至下一日。 */
46	  endMin: number;
47	}
48	
49	const DOW_BY_NAME: Record<string, number> = {
50	  sun: 0,
51	  mon: 1,
52	  tue: 2,
53	  wed: 3,
54	  thu: 4,
55	  fri: 5,
56	  sat: 6,
57	};
58	
59	/** 星期序号的显示名(0=周日 .. 6=周六)。 */
60	const DOW_NAMES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
61	
62	/** 一周分钟数(7 * 1440)。 */
63	const WEEK_MINUTES = 7 * 1440;
64	
65	/**
66	 * 单个窗口相对开始日的最大结束分钟(两天):分类只对每个当地日期回看
67	 * 上一日开始的窗口,故规范形窗口最长跨至下一日结束,更长的时间段必须
68	 * 拆成多个窗口表示。
69	 */
70	const MAX_WINDOW_END_MIN = 2 * 1440;
71	
72	/** 解析 HH:mm 为当日分钟数;allow24 时另接受 24:00(=1440)。无效返回 null。 */
73	function parseHm(raw: string, allow24: boolean): number | null {
74	  const m = /^(\d{2}):(\d{2})$/.exec(raw);
75	  if (!m) return null;
76	  const h = Number(m[1]);
77	  const mi = Number(m[2]);
78	  if (mi > 59) return null;
79	  if (h > 23) {
80	    if (allow24 && h === 24 && mi === 0) return 1440;
81	    return null;
82	  }
83	  return h * 60 + mi;
84	}
85	
86	/**
87	 * 解析每周运行时间表文本。每行一个窗口:<星期> <开始 HH:mm> <结束 HH:mm>;
88	 * 空行与 # 之后的注释忽略。星期为 mon..sun(不区分大小写)。开始限
89	 * 00:00-23:59,结束另可 24:00;同值起止拒绝;结束早于开始跨至下一日。
90	 * 重叠或重复窗口不在此拒绝,分类时取并集。非法时返回错误消息字符串。
91	 */
92	export function parseSchedule(text: string): ScheduleWindow[] | string {
93	  const windows: ScheduleWindow[] = [];
94	  const lines = text.split(/\r\n|\r|\n/);
95	  for (let i = 0; i < lines.length; i++) {
96	    const hash = lines[i].indexOf('#');
97	    const line = (hash === -1 ? lines[i] : lines[i].slice(0, hash)).trim();
98	    if (line === '') continue;
99	    const where = `line ${i + 1}`;
100	    const parts = line.split(/\s+/);
101	    if (parts.length !== 3) {
102	      return `${where}: expect '<weekday> <start HH:mm> <end HH:mm>' (weekday: mon..sun)`;
103	    }
104	    // 只认对象自身的星期键,避免 constructor/__proto__/toString 等原型名被
105	    // 误当成合法星期(那些名字解析为 undefined,但用 in/点访问会命中原型)。
106	    const dow = Object.hasOwn(DOW_BY_NAME, parts[0].toLowerCase())
107	      ? DOW_BY_NAME[parts[0].toLowerCase() as keyof typeof DOW_BY_NAME]
108	      : undefined;
109	    if (dow === undefined) {
110	      return `${where}: unknown weekday '${parts[0]}' (expect mon, tue, wed, thu, fri, sat or sun)`;
111	    }
112	    const start = parseHm(parts[1], false);
113	    if (start === null) {
114	      return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
115	    }
116	    const end = parseHm(parts[2], true);
117	    if (end === null) {
118	      return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
119	    }
120	    if (end === start) {
121	      return `${where}: start and end must differ (both are '${parts[1]}')`;
122	    }
123	    // 结束早于开始即跨至下一日,尾段沿用开始日规则(周日可跨至周一)。
124	    const endMin = end < start ? end + 1440 : end;
125	    windows.push({ startDow: dow, startMin: start, endMin });
126	  }
127	  return windows;
128	}
129	
130	/**
131	 * 把每周运行窗口规范化为并集的最简形式:按周分钟(0..10079)展开为覆盖
132	 * 集合(结束越过周界的窗口取模回卷),再合并为按周分钟升序、互不重叠、
133	 * 互不相邻的窗口列表;超过两天的连续覆盖按每个窗口最多跨至下一日结束
134	 * 切分(分类只回看上一日开始的窗口)。窗口顺序、重复与等价拆分(如
135	 * mon 08:00-12:00 加 mon 12:00-18:00 对比 mon 08:00-18:00)不影响规范形,
136	 * 故规范形相同当且仅当每周运行窗口的并集相同。空表(零个窗口)的规范形
137	 * 为空数组。
138	 */
139	export function canonicalizeWindows(windows: ScheduleWindow[]): ScheduleWindow[] {
140	  const covered = new Uint8Array(WEEK_MINUTES);
141	  for (const w of windows) {
142	    const s = w.startDow * 1440 + w.startMin;
143	    const e = w.startDow * 1440 + w.endMin;
144	    for (let m = s; m < e; m++) covered[m % WEEK_MINUTES] = 1;
145	  }
146	  const out: ScheduleWindow[] = [];
147	  let m = 0;
148	  while (m < WEEK_MINUTES) {
149	    if (covered[m] === 0) {
150	      m++;
151	      continue;
152	    }
153	    const s = m;
154	    while (m < WEEK_MINUTES && covered[m] === 1) m++;
155	    // 连续覆盖段 [s, m):切成每个窗口最多跨至下一日结束(分类只回看一天)。
156	    let cur = s;
157	    while (cur < m) {
158	      const startDow = Math.floor(cur / 1440);
159	      const end = Math.min(m, startDow * 1440 + MAX_WINDOW_END_MIN);
160	      out.push({ startDow, startMin: cur - startDow * 1440, endMin: end - startDow * 1440 });
161	      cur = end;
162	    }
163	  }
164	  return out;
165	}
166	
167	/**
168	 * 时间表的展示形式:`dow HH:mm-HH:mm` 列表(逗号分隔);结束可跨夜,
169	 * 小时可大于 24(相对开始日)。零个窗口显示为 `(no running windows)`。
170	 */
171	export function formatSchedule(windows: ScheduleWindow[]): string {
172	  if (windows.length === 0) return '(no running windows)';
173	  const hm = (min: number): string =>
174	    `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
175	  return windows
176	    .map((w) => `${DOW_NAMES[w.startDow]} ${hm(w.startMin)}-${hm(w.endMin)}`)
177	    .join(', ');
178	}
179	
180	/**
181	 * 解析存储中的时间表字段(窗口数组,元素为 {startDow, startMin, endMin}):
182	 * startDow 0..6,startMin 0..1439,endMin 大于 startMin 且不超过两天(规范
183	 * 形窗口最多跨至下一日结束,与分类的回看口径一致)。非法返回 null,由
184	 * 调用方按损坏数据处理。
185	 */
186	export function validateStoredSchedule(value: unknown): ScheduleWindow[] | null {
187	  if (!Array.isArray(value)) return null;
188	  const out: ScheduleWindow[] = [];
189	  for (const w of value) {
190	    if (w === null || typeof w !== 'object') return null;
191	    const o = w as Record<string, unknown>;
192	    if (
193	      !Number.isSafeInteger(o.startDow) ||
194	      (o.startDow as number) < 0 ||
195	      (o.startDow as number) > 6 ||
196	      !Number.isSafeInteger(o.startMin) ||
197	      (o.startMin as number) < 0 ||
198	      (o.startMin as number) > 1439 ||
199	      !Number.isSafeInteger(o.endMin) ||
200	      (o.endMin as number) <= (o.startMin as number) ||
201	      (o.endMin as number) > MAX_WINDOW_END_MIN
202	    ) {
203	      return null;
204	    }
205	    out.push({
206	      startDow: o.startDow as number,
207	      startMin: o.startMin as number,
208	      endMin: o.endMin as number,
209	    });
210	  }
211	  return out;
212	}
213	
214	interface Period {
215	  /** 时段起点(含),epoch 秒。 */
216	  start: number;
217	  /** 时段终点(不含),epoch 秒。 */
218	  end: number;
219	}
220	
221	/** 墙钟午夜(按 UTC 解释的 epoch 秒)对应的星期,0=周日。1970-01-01 为周四。 */
222	function dowOfNaive(naiveMidnight: number): number {
223	  const days = Math.floor(naiveMidnight / 86400);
224	  return (((days + 4) % 7) + 7) % 7;
225	}
226	
227	/**
228	 * 把 [from, to) 按每周时间表分为运行与非运行两类实际 UTC 时段,两类合计
229	 * 恰好等于查询范围(每秒只属一类)。分类按实际时刻的当地日期与墙钟:
230	 * 墙钟段切分自命名时区(段内偏移恒定、当地日期单一),窗口墙钟区间与段
231	 * 墙钟区间求交后换算回 UTC;夏令时跳过的墙钟没有实际时刻,不虚构覆盖,
232	 * 回拨重复的墙钟两段实际时段各自分类,不套固定偏移或日长。
233	 */
234	export function classifyPeriods(
235	  fmt: Intl.DateTimeFormat,
236	  from: number,
237	  to: number,
238	  windows: ScheduleWindow[],
239	): { running: Period[]; nonRunning: Period[] } {
240	  const raw: Period[] = [];
241	  if (windows.length > 0) {
242	    // 各当地日期生效的窗口墙钟区间(按墙钟午夜缓存):本日开始的窗口,以及
243	    // 上一日开始、跨至本日的窗口尾段。
244	    const wallByDate = new Map<string, Array<[number, number]>>();
245	    const wallIntervalsOf = (label: string): Array<[number, number]> => {
246	      const cached = wallByDate.get(label);
247	      if (cached) return cached;
248	      const dayNaive = parseUtcDate(label) as number;
249	      const wall: Array<[number, number]> = [];
250	      for (const w of windows) {
251	        for (const startNaive of [dayNaive, dayNaive - 86400]) {
252	          if (dowOfNaive(startNaive) !== w.startDow) continue;
253	          wall.push([startNaive + w.startMin * 60, startNaive + w.endMin * 60]);
254	        }
255	      }
256	      wallByDate.set(label, wall);
257	      return wall;
258	    };
259	    for (const seg of wallSegments(fmt, from, to)) {
260	      const wall = wallIntervalsOf(seg.label);
261	      if (wall.length === 0) continue;
262	      // 段内偏移恒定,墙钟区间随 UTC 线性平移。
263	      const ws = seg.start + seg.offset;
264	      const we = seg.end + seg.offset;
265	      for (const [a, b] of wall) {
266	        const lo = Math.max(a, ws);
267	        const hi = Math.min(b, we);
268	        if (lo < hi) raw.push({ start: lo - seg.offset, end: hi - seg.offset });
269	      }
270	    }
271	    raw.sort((a, b) => a.start - b.start);
272	  }
273	  // 重叠或重复窗口取并集。
274	  const running: Period[] = [];
275	  for (const r of raw) {
276	    const last = running[running.length - 1];
277	    if (last && r.start <= last.end) {
278	      if (r.end > last.end) last.end = r.end;
279	    } else {
280	      running.push({ start: r.start, end: r.end });
281	    }
282	  }
283	  const nonRunning: Period[] = [];
284	  let cursor = from;
285	  for (const r of running) {
286	    if (cursor < r.start) nonRunning.push({ start: cursor, end: r.start });
287	    cursor = r.end;
288	  }
289	  if (cursor < to) nonRunning.push({ start: cursor, end: to });
290	  return { running, nonRunning };
291	}
292	
293	/**
294	 * 分组运行/非运行时段能耗报表:按本地每周运行时间表把 [from, to) 分为
295	 * 两类时段,分别按当时生效成员核查能耗。只读,不写入数据。返回进程退出码。
296	 */
297	export function cmdGroupScheduleReport(opts: {
298	  id: string;
299	  /** 本地每周运行时间表文件路径(只读)。 */
300	  schedulePath: string;
301	  from: number;
302	  to: number;
303	  /** 解释时间表的 IANA 时区;省略为 UTC。 */
304	  tz?: string;
305	  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
306	  maxInterval?: number;
307	}): number {
308	  const tzName = opts.tz ?? 'UTC';
309	  const tz = loadTimezone(tzName);
310	  if (!tz) {
311	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
312	    return 2;
313	  }
314	
315	  let text: string;
316	  try {
317	    text = readFileSync(opts.schedulePath, 'utf8');
318	  } catch (e) {
319	    err(`cannot read schedule file ${opts.schedulePath}: ${(e as Error).message}`);
320	    return 1;
321	  }
322	  const parsed = parseSchedule(text);
323	  if (typeof parsed === 'string') {
324	    err(`invalid schedule file ${opts.schedulePath}: ${parsed}`);
325	    return 2;
326	  }
327	  const windows = parsed;
328	
329	  let groups: Group[];
330	  try {
331	    groups = loadGroups(groupFilePath());
332	  } catch (e) {
333	    if (e instanceof StoreError) {
334	      err(e.message);
335	      return 1;
336	    }
337	    throw e;
338	  }
339	  const group = groups.find((g) => g.id === opts.id);
340	  if (!group) {
341	    err(`unknown group '${opts.id}'`);
342	    return 1;
343	  }
344	
345	  let seriesByDevice: Map<string, Reading[]>;
346	  try {
347	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
348	  } catch (e) {
349	    if (e instanceof StoreError) {
350	      err(e.message);
351	      return 1;
352	    }
353	    throw e;
354	  }
355	
356	  const { running, nonRunning } = classifyPeriods(tz, opts.from, opts.to, windows);
357	
358	  console.log(`group: ${group.id}`);
359	  console.log(`schedule: ${opts.schedulePath} (${windows.length} window(s))`);
360	  console.log(`timezone: ${tzName}`);
361	  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);
362	
363	  const classes: Array<{ name: string; periods: Period[] }> = [
364	    { name: 'running', periods: running },
365	    { name: 'non-running', periods: nonRunning },
366	  ];
367	  let incomplete = false;
368	  const coverage: number[] = [];
369	  for (const c of classes) {
370	    let valid = 0;
371	    let anomaly = 0;
372	    let unknown = 0;
373	    let gapUnknown = 0;
374	    const gaps: GapDetail[] = [];
375	    let consumption = 0n;
376	    for (const p of c.periods) {
377	      const stats = computeGroupSegment(
378	        group.versions,
379	        seriesByDevice,
380	        p.start,
381	        p.end,
382	        opts.maxInterval,
383	      );
384	      valid += stats.valid;
385	      anomaly += stats.anomaly;
386	      unknown += stats.unknown;
387	      gapUnknown += stats.gapUnknown;
388	      mergeGaps(gaps, stats.gaps);
389	      consumption += stats.consumption;
390	    }
391	    let seconds = 0;
392	    for (const p of c.periods) seconds += p.end - p.start;
393	    coverage.push(seconds);
394	    const classIncomplete = anomaly > 0 || unknown > 0;
395	    if (classIncomplete) incomplete = true;
396	
397	    const consumptionText =
398	      valid > 0
399	        ? `consumption=${formatKwh(consumption)} kWh (estimate)`
400	        : 'consumption=n/a (no valid coverage)';
401	    let line =
402	      `  class=${c.name}  ${consumptionText}` +
403	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
404	    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
405	    if (classIncomplete) line += '  INCOMPLETE';
406	    console.log(line);
407	    for (const p of c.periods) {
408	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
409	    }
410	    for (const g of gaps) {
411	      console.log(formatGapLine(g));
412	    }
413	  }
414	
415	  const status = incomplete
416	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
417	    : 'status=complete';
418	  console.log(
419	    `  summary: group=${group.id}  running=${coverage[0]}s  non-running=${coverage[1]}s` +
420	      `  total=${opts.to - opts.from}s  ${status}`,
421	  );
422	  return 0;
423	}
424

