363	/**
364	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
365	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
366	 */
367	function deviceSeries(device: string): Reading[] {
368	  const all = loadStore(dataFilePath());
369	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
370	  for (let i = 1; i < series.length; i++) {
371	    if (series[i].ts === series[i - 1].ts) {
372	      throw new StoreError(
373	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
374	      );
375	    }
376	  }
377	  return series;
378	}
379	
380	/**
381	 * 分组规则的评估环境:绑定分组与全库设备时序。
382	 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
383	 */
384	interface GroupEnv {
385	  kind: 'group';
386	  group: Group;
387	  byDevice: Map<string, Reading[]>;
388	}
389	
390	interface DeviceEnv {
391	  kind: 'device';
392	  series: Reading[];
393	}
394	
395	type RuleEnv = DeviceEnv | GroupEnv;
396	
397	/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
398	function prepareEnv(rule: AlertRule): RuleEnv {
399	  if (rule.targetType === 'device') {
400	    return { kind: 'device', series: deviceSeries(rule.targetId) };
401	  }
402	  const groups = loadGroups(groupFilePath());
403	  const group = groups.find((g) => g.id === rule.targetId);
404	  if (!group) {
405	    throw new StoreError(
406	      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
407	    );
408	  }
409	  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
410	  return { kind: 'group', group, byDevice };
411	}
412	
413	/** 一天的有效/异常/未知覆盖秒数后缀;采用间隔限制时附上过长间隔造成的未知秒数。 */
414	function coverageSuffix(
415	  stats: Pick<DayStats, 'valid' | 'anomaly' | 'unknown' | 'gapUnknown'>,
416	  limited: boolean,
417	): string {
418	  const base = `valid=${stats.valid}s anomaly=${stats.anomaly}s unknown=${stats.unknown}s`;
419	  return limited ? `${base} gap=${stats.gapUnknown}s` : base;
420	}
421	
422	/**
423	 * 消耗比较短语:无有效覆盖时明确表示消耗无法计算(不显示 0、也不触发或恢复);
424	 * 有效(含零增长)时给出固定三位小数消耗及与阈值的比较。
425	 */
426	function consumptionCompare(stats: DayStats, threshold: bigint): string {
427	  if (stats.valid === 0) return 'consumption=n/a (no valid coverage)';
428	  const exceeded = stats.consumption > threshold;
429	  return (
430	    `consumption=${formatKwh(stats.consumption)} kWh ` +
431	    `${exceeded ? '>' : '<='} threshold=${formatKwh(threshold)} kWh`
432	  );
433	}
434	
435	/** 一天各实际 UTC 时段的展示行(时段按实际时刻升序)。 */
436	function periodLines(periods: LocalDayPeriod[]): string[] {
437	  return periods.map((p) => `    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
438	}
439	
440	/** 一天内过长区间明细的展示行(指出相关设备与原始相邻读数时刻)。 */
441	function gapLines(stats: Pick<DayStats, 'gaps'>, rule: AlertRule): string[] {
442	  return stats.gaps.map((g) => formatGapLine(g, rule.targetType === 'device' ? rule.targetId : undefined));
443	}
444	
445	/** 规则时区的墙钟格式化器;存储载入时已校验,此处不会失败。 */
446	function ruleFormat(rule: AlertRule): Intl.DateTimeFormat {
447	  const fmt = loadTimezone(rule.tz);
448	  if (fmt === null) {
449	    throw new StoreError(`rule '${rule.id}' has invalid timezone '${rule.tz}' in storage`);
450	  }
451	  return fmt;
452	}
453	
454	/**
455	 * 规则在一个当地日期上实际参与判定的 UTC 时段:全天模式为该日期的全部
456	 * 实际时段;非运行模式为这些时段按规则固定的每周运行时间表分类后的非
457	 * 运行部分(分类沿用 group schedule-report 的口径:按实际时刻的当地日期
458	 * 与墙钟,回拨重复小时各自分类,跳过时段不虚构)。同一日期的不连续时段
459	 * 分别分类后合并在同一日期下参与一次判定。
460	 */
461	function ruleDayPeriods(rule: AlertRule, fmt: Intl.DateTimeFormat, day: LocalDay): LocalDayPeriod[] {
462	  if (rule.schedule === undefined) return day.periods;
463	  const out: LocalDayPeriod[] = [];
464	  for (const p of day.periods) {
465	    out.push(...classifyPeriods(fmt, p.start, p.end, rule.schedule).nonRunning);
466	  }
467	  return out;
468	}
469	
470	/**
471	 * 计算规则在给定 UTC 时段集合上的统计(这些时段属于同一当地日期)。
472	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径;
473	 * 日界线、时间表边界与成员切换都不重置各设备原读数区间的分摊起点。
474	 * maxInterval 为规则固定的采样间隔限制(省略为无上限)。
475	 */
476	function computeRuleDay(env: RuleEnv, periods: LocalDayPeriod[], maxInterval?: number): DayStats {
477	  let valid = 0;
478	  let anomaly = 0;
479	  let unknown = 0;
480	  let gapUnknown = 0;
481	  const gaps: GapDetail[] = [];
482	  let consumption = 0n;
483	  for (const p of periods) {
484	    if (env.kind === 'device') {
485	      const s = computeDay(env.series, p.start, p.end, maxInterval);
486	      valid += s.valid;
487	      anomaly += s.anomaly;
488	      unknown += s.unknown;
489	      gapUnknown += s.gapUnknown;
490	      mergeGaps(gaps, s.gaps);
491	      consumption += s.consumption;
492	    } else {
493	      const s = computeGroupSegment(env.group.versions, env.byDevice, p.start, p.end, maxInterval);
494	      valid += s.valid;
495	      anomaly += s.anomaly;
496	      unknown += s.unknown;
497	      gapUnknown += s.gapUnknown;
498	      mergeGaps(gaps, s.gaps);
499	      consumption += s.consumption;
500	    }
501	  }
502	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption };
503	}
504	
505	/**
506	 * 创建规则。相同标识、同目标类型、同目标标识、等价阈值、同时区(规范名)、
507	 * 同采样间隔限制及同模式(非运行模式比较每周运行窗口并集,不比较文件路径)
508	 * 重试成功且不重复创建;任一不同即报冲突。设备必须已有存储读数;分组必须
509	 * 已配置。非运行模式(带固定时间表,仅分组规则)的创建与同参重试都先检查
510	 * 所用存储与全库重复读数身份。返回进程退出码。
511	 */
512	export function cmdRuleCreate(opts: {
513	  id: string;
514	  targetType: RuleTargetType;
515	  targetId: string;
516	  thresholdMilli: bigint;
517	  /** 规范 IANA 时区名(调用方已解析;省略时传 'UTC')。 */
518	  tz: string;
519	  /** 最大采样间隔限制(正整数秒);省略表示无上限,创建后固定。 */
520	  maxInterval?: number;
521	  /** 非运行模式的每周运行时间表(已解析并规范化的窗口并集);省略为全天
522	   *  模式。仅分组规则可带;创建时保存解析结果,与原文件后续变化无关。 */
523	  schedule?: ScheduleWindow[];
524	}): number {
525	  const statePath = alertFilePath();
526	  let state: AlertState;
527	  try {
528	    state = loadAlertState(statePath);
529	  } catch (e) {
530	    if (e instanceof StoreError) {
531	      err(e.message);
532	      return 1;
533	    }
534	    throw e;
535	  }
536	
537	  // 非运行模式:新模式创建与同参重试都先检查所用存储(分组、读数)及全库
538	  // 重复读数身份,再比较参数或写入。
539	  let groups: Group[] | undefined;
540	  if (opts.schedule !== undefined) {
541	    try {
542	      groups = loadGroups(groupFilePath());
543	      loadCheckedSeriesByDevice(loadStore(dataFilePath()));
544	    } catch (e) {
545	      if (e instanceof StoreError) {
546	        err(e.message);
547	        return 1;
548	      }
549	      throw e;
550	    }
551	  }
552	
553	  const got = `${opts.targetType}=${opts.targetId}`;
554	  const existing = state.rules.find((r) => r.id === opts.id);
555	  if (existing) {
556	    if (
557	      existing.targetType === opts.targetType &&
558	      existing.targetId === opts.targetId &&
559	      existing.thresholdMilli === opts.thresholdMilli &&
560	      existing.tz === opts.tz &&
561	      existing.maxInterval === opts.maxInterval &&
562	      scheduleEquals(existing.schedule, opts.schedule)
563	    ) {
564	      console.log(
565	        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
566	          `threshold=${formatKwh(existing.thresholdMilli)} kWh tz=${existing.tz} ` +
567	          `max-interval=${maxIntervalText(existing.maxInterval)} ${modeText(existing)}); unchanged`,
568	      );
569	      return 0;
570	    }
571	    err(
572	      `rule '${opts.id}' already exists with different parameters ` +
573	        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh ` +
574	        `tz=${existing.tz} max-interval=${maxIntervalText(existing.maxInterval)} ${modeText(existing)}, ` +
575	        `got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
576	        `tz=${opts.tz} max-interval=${maxIntervalText(opts.maxInterval)} ${modeText(opts)}); conflict`,
577	    );
578	    return 1;
579	  }
580	
581	  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
582	  try {
583	    if (opts.targetType === 'device') {
584	      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
585	      if (!devices.has(opts.targetId)) {
586	        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
587	        return 1;
588	      }
589	    } else {
590	      const known = groups ?? loadGroups(groupFilePath());
591	      if (!known.some((g) => g.id === opts.targetId)) {
592	        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
593	        return 1;
594	      }
595	    }
596	  } catch (e) {
597	    if (e instanceof StoreError) {
598	      err(e.message);
599	      return 1;
600	    }
601	    throw e;
602	  }
603	
604	  state.rules.push({
605	    id: opts.id,
606	    targetType: opts.targetType,
607	    targetId: opts.targetId,
608	    thresholdMilli: opts.thresholdMilli,
609	    tz: opts.tz,
610	    maxInterval: opts.maxInterval,
611	    schedule: opts.schedule,
612	  });
613	  try {
614	    saveAlertState(statePath, state);
615	  } catch (e) {
616	    if (e instanceof StoreError) {
617	      err(e.message);
618	      return 1;
619	    }
620	    throw e;
621	  }
622	  console.log(
623	    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
624	      `tz=${opts.tz} max-interval=${maxIntervalText(opts.maxInterval)} ${modeText(opts)}`,
625	  );
626	  return 0;
627	}
628	
629	/** 列出全部规则(含目标类型、时区、采样间隔限制、模式及固定时间表)。只读。返回进程退出码。 */
630	export function cmdRuleList(): number {
631	  let state: AlertState;
632	  try {
633	    state = loadAlertState(alertFilePath());
634	  } catch (e) {
635	    if (e instanceof StoreError) {
636	      err(e.message);
637	      return 1;
638	    }
639	    throw e;
640	  }
641	  if (state.rules.length === 0) {
642	    console.log('no rules defined');
643	    return 0;
644	  }
645	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
646	  for (const r of rules) {
647	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
648	    console.log(
649	      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  ` +
650	        `tz=${r.tz}  max-interval=${maxIntervalText(r.maxInterval)}  ${modeText(r)}  open alerts=${open}`,
651	    );
652	  }
653	  return 0;
654	}
655	
656	/**
657	 * 评估规则在连续完整当地日期范围 [from, to)(规则时区的 YYYY-MM-DD,起日含、
658	 * 止日不含)上的超限情况。每个日期统计归属该日期的全部实际 UTC 时段,一次
659	 * 评估只作一次判定;整日被跳过的日期标明跳过,不判定、不创建也不恢复告警。
660	 * 非运行模式的规则每天只取这些时段中的非运行部分参与判定(运行时段的异常
661	 * 或未知不阻止判定);没有非运行秒数的日期标明原因,同样不判定、不创建也
662	 * 不恢复。全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途
663	 * 任一存储或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
664	 */
665	export function cmdEvaluate(opts: { ruleId: string; from: string; to: string }): number {
666	  const statePath = alertFilePath();
667	  let state: AlertState;
668	  let rule: AlertRule;
669	  let env: RuleEnv;
670	  let fmt: Intl.DateTimeFormat;
671	  try {
672	    state = loadAlertState(statePath);
673	    const found = state.rules.find((r) => r.id === opts.ruleId);
674	    if (!found) {
675	      err(`unknown rule '${opts.ruleId}'`);
676	      return 1;
677	    }
678	    rule = found;
679	    env = prepareEnv(rule);
680	    fmt = ruleFormat(rule);
681	  } catch (e) {
682	    if (e instanceof StoreError) {
683	      err(e.message);
684	      return 1;
685	    }
686	    throw e;
687	  }
688	
689	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
690	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
691	  const alertIds = new Set(state.alerts.map((a) => a.id));
692	
693	  const threshold = rule.thresholdMilli;
694	  const limited = rule.maxInterval !== undefined;
695	  const lines: string[] = [];
696	  for (const { label, day } of localDateRange(fmt, opts.from, opts.to)) {
697	    if (day === null) {
698	      // 整日被跳过(无实际时段):不判定、不触发也不恢复。
699	      lines.push(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})  no alert action`);
700	      continue;
701	    }
702	    // 全天模式为当天全部实际时段;非运行模式只取其中的非运行部分。
703	    const periods = ruleDayPeriods(rule, fmt, day);
704	    let periodSeconds = 0;
705	    for (const p of periods) periodSeconds += p.end - p.start;
706	    if (periodSeconds === 0) {
707	      // 非运行模式且当天没有非运行秒数:说明原因,不判定、不触发也不恢复。
708	      lines.push(
709	        `  ${label}  NO NON-RUNNING COVERAGE (running windows cover the whole local date)  no alert action`,
710	      );
711	      continue;
712	    }
713	    const stats = computeRuleDay(env, periods, rule.maxInterval);
714	    const coverage = coverageSuffix(stats, limited);
715	    if (stats.unknown > 0 || stats.anomaly > 0) {
716	      // 有未知或下降覆盖:不可判定,不触发也不恢复。无有效覆盖时明确显示
717	      // 消耗无法计算(不显示 0);仍有部分有效覆盖时只给覆盖与原因,不与阈值比较。
718	      const head =
719	        stats.valid === 0
720	          ? `  ${label}  undecidable  ${consumptionCompare(stats, threshold)}  (${coverage})  no alert action`
721	          : `  ${label}  undecidable (${coverage})  no alert action`;
722	      lines.push(head);
723	      lines.push(...periodLines(periods));
724	      lines.push(...gapLines(stats, rule));
725	      continue;
726	    }
727	    const exceeded = stats.consumption > threshold;
728	    const cmp = consumptionCompare(stats, threshold);
729	    const open = state.alerts.find(
730	      (a) => a.ruleId === rule.id && a.date === label && a.status === 'triggered',
731	    );
732	    if (exceeded) {
733	      if (open) {
734	        // 重复超限:保留原标识,不新增事件。
735	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered  ${coverage}`);
736	      } else {
737	        const id = `alert-${state.nextAlertNum++}`;
738	        if (alertIds.has(id)) {
739	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
740	          return 1;
741	        }
742	        alertIds.add(id);
743	        state.alerts.push({
744	          id,
745	          ruleId: rule.id,
746	          date: label,
747	          status: 'triggered',
748	          acknowledged: false,
749	          events: [
750	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
751	          ],
752	        });
753	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)  ${coverage}`);
754	      }
755	    } else {
756	      if (open) {
757	        open.status = 'recovered';
758	        open.events.push({
759	          seq: state.nextEventSeq++,
760	          type: 'recovered',
761	          consumptionMilli: stats.consumption.toString(),
762	        });
763	        lines.push(`  ${label}  ${cmp}  NORMAL  alert ${open.id} recovered  ${coverage}`);
764	      } else {
765	        lines.push(`  ${label}  ${cmp}  NORMAL  no alert  ${coverage}`);
766	      }
767	    }
768	    lines.push(...periodLines(periods));
769	  }
770	
771	  try {
772	    saveAlertState(statePath, state);
773	  } catch (e) {
774	    if (e instanceof StoreError) {
775	      err(e.message);
776	      return 1;
777	    }
778	    throw e;
779	  }
780	
781	  console.log(
782	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
783	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}  ${modeText(rule)}`,
784	  );
785	  for (const line of lines) console.log(line);
786	  return 0;
787	}
788	
789	/**
790	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
791	 * 给定日期范围时按规则时区的当地日期逐日展示当前计算的消耗或不可判定原因、
792	 * 实际 UTC 时段与各次告警;省略范围时展示有告警记录的全部日期。触发/恢复
793	 * 事件中的消耗为评估当时记录,不随后续数据变化改写。返回进程退出码。
794	 */
795	export function cmdAlerts(opts: { ruleId: string; from?: string; to?: string }): number {
796	  let state: AlertState;
797	  let rule: AlertRule;
798	  let env: RuleEnv;
799	  let fmt: Intl.DateTimeFormat;
800	  try {
801	    state = loadAlertState(alertFilePath());
802	    const found = state.rules.find((r) => r.id === opts.ruleId);
803	    if (!found) {
804	      err(`unknown rule '${opts.ruleId}'`);
805	      return 1;
806	    }
807	    rule = found;
808	    env = prepareEnv(rule);
809	    fmt = ruleFormat(rule);
810	  } catch (e) {
811	    if (e instanceof StoreError) {
812	      err(e.message);
813	      return 1;
814	    }
815	    throw e;
816	  }
817	
818	  // 待展示的当地日期(升序):给定范围时为范围内全部日期;省略范围时为有告警
819	  // 记录的全部日期。
820	  let labels: string[];
821	  if (opts.from !== undefined && opts.to !== undefined) {
822	    labels = localDateRange(fmt, opts.from, opts.to).map((e) => e.label);
823	  } else {
824	    labels = [
825	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
826	    ].sort();
827	  }
828	
829	  console.log(
830	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
831	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}  ${modeText(rule)}`,
832	  );
833	  if (labels.length === 0) {
834	    console.log(`  no alerts recorded for rule '${rule.id}'`);
835	    return 0;
836	  }
837	
838	  // 各当地日期的实际 UTC 时段;整日被跳过的日期为 null。日历日期逐日递增,
839	  // 末日后延一天作为切分终点。
840	  const last = parseUtcDate(labels[labels.length - 1]) as number;
841	  const endLabel = formatIsoUtc(last + DAY_SECONDS).slice(0, 10);
842	  const byLabel = new Map<string, LocalDay | null>();
843	  for (const e of localDateRange(fmt, labels[0], endLabel)) byLabel.set(e.label, e.day);
844	
845	  const threshold = rule.thresholdMilli;
846	  const limited = rule.maxInterval !== undefined;
847	  for (const label of labels) {
848	    const day = byLabel.get(label) ?? null;
849	    if (day === null) {
850	      console.log(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})`);
851	    } else {
852	      // 全天模式为当天全部实际时段;非运行模式只取其中的非运行部分。
853	      const periods = ruleDayPeriods(rule, fmt, day);
854	      let periodSeconds = 0;
855	      for (const p of periods) periodSeconds += p.end - p.start;
856	      if (periodSeconds === 0) {
857	        console.log(`  ${label}  NO NON-RUNNING COVERAGE (running windows cover the whole local date)`);
858	      } else {
859	        const stats = computeRuleDay(env, periods, rule.maxInterval);
860	        if (stats.unknown > 0 || stats.anomaly > 0) {
861	          // 不可判定;无有效覆盖时明确显示消耗无法计算,不显示 0 或与阈值比较。
862	          const head =
863	            stats.valid === 0
864	              ? `  ${label}  undecidable  ${consumptionCompare(stats, threshold)}  (${coverageSuffix(stats, limited)})`
865	              : `  ${label}  undecidable (${coverageSuffix(stats, limited)})`;
866	          console.log(head);
867	        } else {
868	          const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
869	          console.log(
870	            `  ${label}  consumption=${formatKwh(stats.consumption)} kWh ` +
871	              `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)  ${coverageSuffix(stats, limited)}`,
872	          );
873	        }
874	        for (const line of periodLines(periods)) console.log(line);
875	        for (const line of gapLines(stats, rule)) console.log(line);
876	      }
877	    }
878	    const alerts = state.alerts
879	      .filter((a) => a.ruleId === rule.id && a.date === label)
880	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
881	    if (alerts.length === 0) {
882	      console.log('    no alerts');
883	      continue;
884	    }
885	    for (const a of alerts) {
886	      console.log(
887	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
888	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
889	      );
890	      const events = a.events
891	        .map((e) => {
892	          const consumption =
893	            e.consumptionMilli !== undefined
894	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
895	              : '';
896	          return `#${e.seq} ${e.type}${consumption}`;
897	        })
898	        .join(', ');
899	      console.log(`      events: ${events}`);
900	    }
901	  }
902	  return 0;
903	}
904	
905	/**
906	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
907	 * 确认不改变超限或恢复状态。返回进程退出码。
908	 */
909	export function cmdAck(alertId: string): number {
910	  const statePath = alertFilePath();
911	  let state: AlertState;
912	  try {
913	    state = loadAlertState(statePath);
914	  } catch (e) {
915	    if (e instanceof StoreError) {
916	      err(e.message);
917	      return 1;
918	    }
919	    throw e;
920	  }
921	  const alert = state.alerts.find((a) => a.id === alertId);
922	  if (!alert) {
923	    err(`unknown alert '${alertId}'`);
924	    return 1;
925	  }
926	  if (alert.acknowledged) {
927	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
928	    return 0;
929	  }
930	  alert.acknowledged = true;
931	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
932	  try {
933	    saveAlertState(statePath, state);
934	  } catch (e) {
935	    if (e instanceof StoreError) {
936	      err(e.message);
937	      return 1;
938	    }
939	    throw e;
940	  }
941	  const rule = state.rules.find((r) => r.id === alert.ruleId);
942	  const target = rule ? ` ${targetLabel(rule)}` : '';
943	  console.log(
944	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
945	  );
946	  return 0;
947	}
