297	interface ParsedOptions {
298	  devices: string[];
299	  from?: number;
300	  to?: number;
301	  tz?: string;
302	  maxInterval?: number;
303	}
304	
305	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
306	function parseMaxInterval(raw: string): number | null {
307	  const v = raw.trim();
308	  if (!/^\d+$/.test(v)) return null;
309	  const n = Number(v);
310	  if (!Number.isSafeInteger(n) || n < 1) return null;
311	  return n;
312	}
