337	    check(S, /no alert action/.test(r.out), 'non-running unknown/anomaly must not trigger or recover');
338	    // 多成员 gap 并集不叠加:同一 [23:00,01:00) 两成员只计一次 3600(union 已并入 5400)。
339	    check(S, countOccurrences(r.out, /gap: device=x/g) === 2, `x gap details listed for its two raw intervals:\n${r.out}`);
340	    check(S, countOccurrences(r.out, /gap: device=y/g) === 1, `y gap detail listed once:\n${r.out}`);
341	    // gap 明细指向原始相邻读数时刻,不被日界或 02:00 时点裁短。
342	    check(S, r.out.includes(S2.rawGap1), `gap must reference raw interval ${S2.rawGap1}:\n${r.out}`);
343	    check(S, r.out.includes(S2.rawGap2), `x gap must span the un-clipped raw interval ${S2.rawGap2}:\n${r.out}`);
