529	    check(S, data.readings.find((x) => x.device === 'm' && x.ts === Date.parse('2026-01-06T00:00:00Z') / 1000).milli === '2000',
530	      'undo restores 2.000; replay does not re-change');
531	    // 已撤销修正再“重放”仍返回原成功结果,不重新应用(值保持 2.000)。
532	    r = run(dir, ['correct', '--request', 'REQ-A',
533	      '--item', '--device', 'm', '--at', '2026-01-06T00:00:00Z', '--expect', '2.000', '--set', '0.500']);
534	    check(S, r.code === 0, `replay of undone correction still rc=0`);
535	    check(S, readJson(dir, 'readings.json').readings.find(
536	      (x) => x.device === 'm' && x.ts === Date.parse('2026-01-06T00:00:00Z') / 1000).milli === '2000',
537	      'replay of undone correction must not re-apply');
538	
539	    // 撤销是数据操作,不自动改检测状态:仍 recovered。
540	    state = readJson(dir, 'alerts.json');
541	    check(S, state.alerts[0].status === 'recovered', 'undo must not auto-change detection status');
542	
543	    // 8) 显式重评再次超限 => 创建“新的未确认”告警 alert-2;旧记录与确认保留。
544	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
545	    check(S, /alert alert-2 triggered \(unacknowledged\)/.test(r.out), `re-exceed creates new alert-2:\n${r.out}`);
546	    state = readJson(dir, 'alerts.json');
547	    check(S, state.alerts.length === 2, 'old and new alerts both retained');
548	    const old = state.alerts.find((a) => a.id === 'alert-1');
549	    const neu = state.alerts.find((a) => a.id === 'alert-2');
550	    check(S, old.status === 'recovered' && old.acknowledged === true, 'old alert stays recovered+acked');
551	    check(S, neu.status === 'triggered' && neu.acknowledged === false && neu.events.length === 1,
552	      'new alert is triggered/unacknowledged with its own event');
553	  } finally {
554	    rmSync(dir, { recursive: true, force: true });
555	  }
556	}
557	
558	// 批量日期评估写入失败 => 返回 1、无部分成功输出、三个业务存储内容与存在状态不变;
559	// 解除故障后重试成功,告警与事件编号不冲突。
560	function scenarioWriteFailure() {
561	  const S = 'batch evaluate write failure atomicity + id/seq non-collision on retry';
562	  const dir = makeDataDir();
563	  try {
564	    // 两个可判定且超限的日期(周一、周二),空表全天非运行,阈值 1。
565	    write(join(dir, 'r.csv'), ['device,time,reading',
566	      'm,2026-01-05T00:00:00Z,0.000',
567	      'm,2026-01-06T00:00:00Z,2.000', // 周一 +2.000
568	      'm,2026-01-07T00:00:00Z,4.000', // 周二 +2.000
569	      '',
570	    ].join('\n'));
571	    write(join(dir, 'empty.txt'), '\n');
572	    let r = run(dir, ['import', 'r.csv']);
573	    check(S, r.code === 0, `import rc=${r.code} ${r.err}`);
574	    r = run(dir, ['group', 'configure', '--id', 'g', '--at', '2026-01-01T00:00:00Z', '--device', 'm']);
575	    check(S, r.code === 0, `group rc=${r.code} ${r.err}`);
576	    r = run(dir, ['rule', 'create', '--id', 'nr', '--group', 'g', '--threshold', '1', '--schedule', 'empty.txt']);
577	    check(S, r.code === 0, `rule rc=${r.code} ${r.err}`);
578	
579	    const before = storeSnapshot(dir);
580	    const alertsPath = join(dir, 'alerts.json');
581	    // 可控本地故障:把目标业务存储置为不可更改(chflags uchg),使临时文件 rename 失败。
582	    execFileSync('chflags', ['uchg', alertsPath]);
583	    try {
584	      r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-07']);
585	      check(S, r.code === 1, `failed batch evaluate must be rc=1, got ${r.code}`);
586	      check(S, !/EXCEEDED|alert-\d|recovered/i.test(r.out), `failed evaluate must print no partial success:\n${r.out}`);
587	      check(S, /cannot write storage file/.test(r.err), `must report write failure: ${r.err}`);
588	    } finally {
589	      execFileSync('chflags', ['nouchg', alertsPath]);
590	    }
591	    const diff = sameSnapshot(before, storeSnapshot(dir));
592	    check(S, diff === null, `all three business stores must be unchanged on failure (${diff})`);
593	    // 失败不得占用任何编号:重试成功 => 周一新建 alert-1(不是 alert-3),周二 alert-2。
594	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-07']);
595	    check(S, r.code === 0, `retry after fault cleared rc=${r.code} ${r.err}`);
596	    check(S, /2026-01-05[^\n]*alert alert-1 triggered/.test(r.out) &&
597	      /2026-01-06[^\n]*alert alert-2 triggered/.test(r.out),
598	      `retry must mint alert-1 and alert-2 without collision:\n${r.out}`);
599	    let state = readJson(dir, 'alerts.json');
600	    const seqs = state.alerts.flatMap((a) => a.events.map((e) => e.seq));
601	    check(S, state.alerts.length === 2 && new Set(seqs).size === 2 && seqs.join(',') === '1,2',
602	      `event seqs must be unique 1,2 got ${seqs.join(',')}`);
603	    check(S, state.alerts.every((a) => a.acknowledged === false), 'retry alerts are unacknowledged');
604	
605	    // 再来一个超限日期,确认编号继续不冲突(alert-3 / seq3)。
606	    write(join(dir, 'r2.csv'), 'device,time,reading\nm,2026-01-08T00:00:00Z,6.001\n');
607	    r = run(dir, ['import', 'r2.csv']);
608	    check(S, r.code === 0, `import wed rc=${r.code} ${r.err}`);
609	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-07', '--to', '2026-01-08']);
610	    check(S, /alert alert-3 triggered \(unacknowledged\)/.test(r.out), `third exceed mints alert-3:\n${r.out}`);
611	    state = readJson(dir, 'alerts.json');
612	    check(S, state.nextAlertNum === 4 && state.nextEventSeq === 4, 'counters continue without collision');
613	  } finally {
614	    // 确保故障标志一定解除,再清理临时目录。
615	    try { execFileSync('chflags', ['nouchg', join(dir, 'alerts.json')]); } catch { /* may not exist */ }
616	    rmSync(dir, { recursive: true, force: true });
617	  }
618	}
619	
620	// 同一规则、同一日期:非运行先超限(打开告警),随后数据使非运行变为异常/未知,
621	// 再次评估必须“不恢复”也不新增事件;恢复只发生在之后重新完整评估正常时。
622	function scenarioNoRecoverOnUndecidable() {
623	  const S = 'undecidable non-running neither triggers nor recovers an open alert (same rule/date)';
624	  const dir = makeDataDir();
625	  try {
626	    // 窗口 mon 12:00-18:00。初始非运行两段都有效:[00,12)+2.000、[18,24)+2.000 = 4.000。
627	    write(join(dir, 'r.csv'), ['device,time,reading',
628	      'm,2026-01-05T00:00:00Z,0.000',
629	      'm,2026-01-05T12:00:00Z,2.000',
630	      'm,2026-01-05T18:00:00Z,2.000',
631	      'm,2026-01-06T00:00:00Z,4.000',
632	      '',
633	    ].join('\n'));
634	    write(join(dir, 'win.txt'), 'mon 12:00 18:00\n');
635	    let r = run(dir, ['import', 'r.csv']);
636	    check(S, r.code === 0, `import rc=${r.code} ${r.err}`);
637	    r = run(dir, ['group', 'configure', '--id', 'g', '--at', '2026-01-01T00:00:00Z', '--device', 'm']);
638	    check(S, r.code === 0, `group rc=${r.code} ${r.err}`);
639	    r = run(dir, ['rule', 'create', '--id', 'nr', '--group', 'g', '--threshold', '3', '--schedule', 'win.txt']);
640	    check(S, r.code === 0, `rule rc=${r.code} ${r.err}`);
641	
642	    // 4.000 > 3 => 打开 alert-1。
643	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
644	    check(S, /alert alert-1 triggered \(unacknowledged\)/.test(r.out), `initial exceed opens alert-1:\n${r.out}`);
645	
646	    // 把周二00:00 读数 4.000 改成 1.000:[周一18:00,周二00:00) 变为下降(2.000->1.000),
647	    // 非运行 [18,24) 出现异常 => 当日非运行不可判定。
648	    r = run(dir, ['correct', '--request', 'REQ-DROP',
649	      '--item', '--device', 'm', '--at', '2026-01-06T00:00:00Z', '--expect', '4.000', '--set', '1.000']);
650	    check(S, r.code === 0, `correction to induce decline rc=${r.code} ${r.err}`);
651	
652	    // 再次评估同一日期:不可判定,打开的 alert-1 必须保持 triggered、不新增恢复事件。
653	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
654	    check(S, /undecidable/.test(r.out) && /no alert action/.test(r.out),
655	      `undecidable non-running must take no action:\n${r.out}`);
656	    let state = readJson(dir, 'alerts.json');
657	    let a1 = state.alerts.find((a) => a.id === 'alert-1');
658	    check(S, !!a1 && a1.status === 'triggered' && a1.events.length === 1 &&
659	      a1.events[0].type === 'triggered',
660	      'open alert must not recover and must gain no event on undecidable re-eval');
661	
662	    // alerts 历史:当前不可判定,但告警状态仍为 TRIGGERED,触发时消耗 4.000 保留。
663	    r = run(dir, ['alerts', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
664	    check(S, /2026-01-05[^\n]*undecidable/.test(r.out), `alerts shows undecidable current state:\n${r.out}`);
665	    check(S, /alert alert-1  status=TRIGGERED/.test(r.out), `alert stays TRIGGERED in history:\n${r.out}`);
666	    check(S, /#1 triggered \(consumption=4\.000 kWh\)/.test(r.out), `trigger consumption 4.000 preserved:\n${r.out}`);
667	
668	    // 撤销修正,读数恢复 4.000;数据操作本身仍不自动恢复。
669	    r = run(dir, ['undo', '--request', 'UNDO-DROP', '--target', 'REQ-DROP']);
670	    check(S, r.code === 0, `undo rc=${r.code} ${r.err}`);
671	    state = readJson(dir, 'alerts.json');
672	    a1 = state.alerts.find((a) => a.id === 'alert-1');
673	    check(S, a1.status === 'triggered', 'undo (data op) must not auto-recover');
674	
675	    // 显式重新完整评估且仍超限(4.000>3)=> 保留原告警,不新增。
676	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
677	    check(S, /alert alert-1 remains triggered/.test(r.out), `re-exceeded after undo keeps alert-1:\n${r.out}`);
678	
679	    // 正面对照:把读数改为有效且非运行消耗恰等于阈值(3.000):将周二00:00 设为 3.000,
680	    // [18,24) 从下降后的当前值需要再修正。先撤销已不存在——直接对 4.000 再做一次修正。
681	    r = run(dir, ['correct', '--request', 'REQ-NORM',
682	      '--item', '--device', 'm', '--at', '2026-01-06T00:00:00Z', '--expect', '4.000', '--set', '3.000']);
683	    check(S, r.code === 0, `correction to normal value rc=${r.code} ${r.err}`);
684	    // 数据操作仍不自动恢复。
685	    state = readJson(dir, 'alerts.json');
686	    check(S, state.alerts[0].status === 'triggered', 'second correction also must not auto-recover');
687	    // 显式完整评估且正常(NR=2.000+1.000=3.000 == 阈值)=> 此刻才恢复,记录恢复消耗 3.000。
688	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
689	    check(S, /alert alert-1 recovered/.test(r.out), `complete normal re-eval must recover:\n${r.out}`);
690	    state = readJson(dir, 'alerts.json');
691	    a1 = state.alerts.find((a) => a.id === 'alert-1');
692	    const rec = a1.events.find((e) => e.type === 'recovered');
693	    check(S, a1.status === 'recovered' && !!rec && rec.consumptionMilli === '3000' && a1.events.length === 2,
694	      'recovery recorded at 3.000 only after complete normal evaluation');
695	    rmSync(join(dir, 'win.txt'));
696	  } finally {
697	    rmSync(dir, { recursive: true, force: true });
698	  }
699	}
700	
701	const scenarios = [
702	  scenarioS1,
703	  scenarioDst,
704	  scenarioS2,
705	  scenarioNoCoverage,
706	  scenarioNoRecoverOnUndecidable,
707	  scenarioBadWeekday,
708	  scenarioLifecycle,
709	  scenarioWriteFailure,
710	];
711	
712	for (const sc of scenarios) {
713	  try {
714	    sc();
715	  } catch (e) {
716	    failures.push(`[${sc.name}] harness error: ${e?.stack ?? e}`);
717	  }
718	}
719	
720	if (failures.length > 0) {
721	  console.error(`\nFAIL: ${failures.length} assertion(s) failed, ${passed} passed`);
722	  for (const f of failures) console.error(`  - ${f}`);
723	  process.exit(1);
724	}
725	console.log(`PASS: all ${passed} assertions across ${scenarios.length} scenarios`);
726

