1	// 电表读数数值:以千分之一 kWh(毫千瓦时)的 BigInt 表示,
2	// 解析、比较、求差、显示全程整数运算,不产生浮点尾差,
3	// 也不受 Number 安全整数范围限制,任意大的十进制输入都精确。
4	
5	const VALUE_RE = /^(\d+)(?:\.(\d{1,3}))?$/;
6	
7	/** 解析 kWh 读数(非负、最多三位小数)为毫千瓦时 BigInt;失败返回 null。 */
8	export function parseKwh(input: string): bigint | null {
9	  const m = VALUE_RE.exec(input);
10	  if (!m) return null;
11	  const intPart = m[1].replace(/^0+(?=\d)/, '');
12	  const frac = (m[2] ?? '').padEnd(3, '0');
13	  return BigInt(intPart) * 1000n + BigInt(frac);
14	}
15	
16	/** 将毫千瓦时 BigInt 格式化为固定三位小数的 kWh 字符串(不用科学计数法)。 */
17	export function formatKwh(milli: bigint): string {
18	  const sign = milli < 0n ? '-' : '';
19	  const abs = milli < 0n ? -milli : milli;
20	  const int = abs / 1000n;
21	  const frac = (abs % 1000n).toString().padStart(3, '0');
22	  return `${sign}${int}.${frac}`;
23	}
