 * 等价拆分不影响等价性;不比较任何文件路径。两边都省略(全天模式)才相等。
 */
function scheduleEquals(a?: ScheduleWindow[], b?: ScheduleWindow[]): boolean {
  if (a === undefined || b === undefined) return a === b;
  const ca = canonicalizeWindows(a);
  const cb = canonicalizeWindows(b);
  return (
    ca.length === cb.length &&
    ca.every(
      (w, i) =>
