 * 分别分类后合并在同一日期下参与一次判定。
 */
function ruleDayPeriods(rule: AlertRule, fmt: Intl.DateTimeFormat, day: LocalDay): LocalDayPeriod[] {
  if (rule.schedule === undefined) return day.periods;
